const vermerk = (s) => (Object.hasOwn(UEBERSETZT, s.muster) ? UEBERSETZT[s.muster] : UEBERSETZT_EINZELN[s.schluessel]);

/** Englische Länderfassungen mit übersetztem Länderinhalt (je Land Muster → Vermerk). */
