      />

      <CtaBand
        eyebrow={w.cta.eyebrow}
        title={w.cta.titel}
        text={at ? w.cta.textAt : w.cta.text}
        primary={{ label: w.cta.primaer, href: "#anfrage" }}
        secondary={at ? { label: w.cta.sekAt, href: pfad("/energiegemeinschaften") } : { label: w.cta.sek, href: pfad("/rechner/kommune") }}
      />
    </div>
  );
}

